#include "recovered_camera_projection_candidate.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");size_t checked=0;for(float fov:{25.2f,60.f,90.f})for(float aspect:{1.f,4.f/3.f,16.f/9.f})for(auto planes:{std::array<float,2>{3,28377.9f},std::array<float,2>{.1f,100.f}}){auto p=recoveredCameraProjectionCandidate(planes[0],planes[1],fov,aspect,false);if(std::abs(p.depth({0,0,-planes[0]}))>2e-6||std::abs(p.depth({0,0,-planes[1]})-1)>2e-6)throw std::runtime_error("near/far depth");float distance=10;float edge=float(std::tan(double(fov)*3.141592653589793/360.0))*distance;auto horizontal=p.clip({edge,0,-distance}),vertical=p.clip({0,edge/aspect,-distance});if(std::abs(horizontal[0]/horizontal[3]-1)>2e-6||std::abs(vertical[1]/vertical[3]-1)>2e-6)throw std::runtime_error("FOV edges");auto vk=recoveredCameraProjectionCandidate(planes[0],planes[1],fov,aspect,true);if(vk.rows[5]!=-p.rows[5]||vk.rows[10]!=p.rows[10])throw std::runtime_error("Vulkan Y conversion");++checked;}size_t rejected=0;for(auto args:{std::array<float,4>{0,100,60,1},std::array<float,4>{3,2,60,1},std::array<float,4>{1,100,180,1},std::array<float,4>{1,100,60,0}}){try{recoveredCameraProjectionCandidate(args[0],args[1],args[2],args[3],false);}catch(const std::runtime_error&){++rejected;}}if(rejected!=4)throw std::runtime_error("projection rejection");std::cout<<"x64 recovered projection candidate passed frusta="<<checked<<" rejected="<<rejected<<" native_bitwise_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
